import org.apache.commons.math3.linear.Array2DRowRealMatrix;
import org.apache.commons.math3.linear.EigenDecomposition;
import org.apache.commons.math3.linear.NonPositiveDefiniteMatrixException;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.linear.SingularMatrixException;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for MultivariateNormalDistribution#density.
 */
public class MultivariateNormalDistribution_density_TriageGen5Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDensityWithCorrectDimension() throws Exception {
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // For standard normal in 2D, density at (0,0) is:
        // (2 * PI)^(-2/2) * (det(I))^-0.5 * exp(0)
        // = (2 * PI)^-1 * 1 * 1 = 1 / (2 * PI)
        double[] vals = {0.0, 0.0};
        double expected = 1.0 / (2.0 * Math.PI);
        double actual = distribution.density(vals);

        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testDensityWithNonZeroMean() throws Exception {
        double[] means = {1.0, -1.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Test at the mean (exponent term should be 0, exp(0)=1)
        double[] vals = {1.0, -1.0};
        double expected = 1.0 / (2.0 * Math.PI);
        double actual = distribution.density(vals);

        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testDensityWithDifferentCovariance() throws Exception {
        double[] means = {0.0};
        double[][] covariances = {{4.0}}; // Variance = 4, StdDev = 2
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // 1D case: (2*PI)^(-1/2) * (4)^(-0.5) * exp(-0.5 * (0-0)^2 / 4)
        // = (2*PI)^(-0.5) * 0.5 * 1
        double[] vals = {0.0};
        double expected = (1.0 / Math.sqrt(2.0 * Math.PI)) * 0.5;
        double actual = distribution.density(vals);

        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testDensityDimensionMismatch() throws Exception {
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Passing 3 values instead of 2
        double[] vals = {0.0, 0.0, 0.0};

        assertThrows(DimensionMismatchException.class, () -> {
            distribution.density(vals);
        });
    }

    @Test
    public void testDensityDimensionMismatchSmall() throws Exception {
        double[] means = {0.0, 0.0};
        double[][] covariances = {{1.0, 0.0}, {0.0, 1.0}};
        MultivariateNormalDistribution distribution = new MultivariateNormalDistribution(means, covariances);

        // Passing 1 value instead of 2
        double[] vals = {0.0};

        assertThrows(DimensionMismatchException.class, () -> {
            distribution.density(vals);
        });
    }
}
